"""Structured -> code: emit an equivalent ``build.py`` and verify it (PROTOCOL.md section 5.4)."""

from __future__ import annotations

import pprint
import re
import textwrap
from pathlib import Path
from typing import Any

from lxml import etree
from pptx import Presentation

from ..render import footer_text, load_deck

HEADER = '''\
"""Deck build script, generated by Personal Present from the structured deck (eject).

Each function builds one slide through the deck SDK. Run by the Present kernel in the code
sandbox; edit freely. `slide.raw` is the python-pptx slide for anything the SDK does not cover.
"""

from present_sdk import Deck

'''


def _slug(text: str) -> str:
    slug = re.sub(r"[^a-z0-9]+", "_", text.lower()).strip("_")
    return slug[:32] or "slide"


def _lit(value: Any, indent: int = 4) -> str:
    text = pprint.pformat(value, width=100, sort_dicts=False)
    return textwrap.indent(text, " " * indent).lstrip()


def _title_of(doc: dict[str, Any]) -> str:
    item = (doc.get("placeholders") or {}).get("title") or {}
    paras = (item.get("text") or {}).get("paragraphs", [])
    return "".join(r.get("t", "") for p in paras for r in p.get("runs", []))


def eject_source(project: Path, deck_rel: str = "deck/deck.json") -> str:
    deck, slides = load_deck(project, deck_rel)
    multi = any(s.get("title") for s in deck.get("sections", []))
    footer = deck.get("footer") or {}
    ftext = footer_text(deck)
    furniture = bool(ftext or footer.get("slide_numbers") or footer.get("date"))
    parts = [HEADER]
    names: list[str] = []
    n = 0
    for section in deck.get("sections", []):
        for sid in section.get("slides", []):
            doc = slides[sid]
            n += 1
            name = f"slide_{n:02d}_{_slug(_title_of(doc) or doc['layout'])}"
            names.append(name)
            sec = repr(section.get("title", "")) if multi else "None"
            body = [f"def {name}(deck):", f"    slide = deck.add_slide({doc['layout']!r}, slide_id={sid!r}, section={sec})"]
            if doc.get("kind") == "generated":
                script = (doc.get("generated") or {}).get("script") or "pass"
                body.append("    # --- generated slide script (inlined) ---")
                body.append(textwrap.indent(script.rstrip(), "    "))
                body.append("    # --- end generated slide script ---")
            else:
                for key, item in (doc.get("placeholders") or {}).items():
                    body.append(f"    slide.fill({key!r}, {_lit(item)})")
                for element in doc.get("elements") or []:
                    body.append(f"    slide.free({_lit(element)})")
            if doc.get("notes"):
                body.append(f"    slide.notes({_lit(doc['notes'])})")
            if doc.get("hidden"):
                body.append('    slide.raw._element.set("show", "0")')
            if furniture:
                body.append(f"    slide.furniture({ftext!r}, {bool(footer.get('slide_numbers'))!r}, {bool(footer.get('date'))!r})")
            parts.append("\n".join(body) + "\n\n\n")
    main = ["def main():", "    deck = Deck.open_template()", f"    deck.properties['Title'] = {deck.get('title', '')!r}"]
    if deck.get("author"):
        main.append(f"    deck.properties['Author'] = {deck['author']!r}")
    for k, v in (deck.get("properties") or {}).items():
        main.append(f"    deck.properties[{k!r}] = {v!r}")
    main += [f"    {name}(deck)" for name in names]
    main += ["    deck.save()", "", "", 'if __name__ == "__main__":', "    main()", ""]
    parts.append("\n".join(main))
    return "".join(parts)


_VOLATILE = ("}id", "}embed", "}link", "}pict")


def normalized_slides(pptx: Path) -> list[str]:
    """Slide XML with relationship ids neutralized, for comparing two builds of the same deck."""
    out = []
    for slide in Presentation(str(pptx)).slides:
        root = etree.fromstring(etree.tostring(slide._element))
        for el in root.iter():
            for attr in list(el.attrib):
                if attr.endswith(_VOLATILE):
                    el.set(attr, "rId")
        out.append(etree.tostring(root, pretty_print=True).decode())
    return out


def compare(a: Path, b: Path) -> str | None:
    """None when the two files have identical slides; otherwise a short unified diff."""
    import difflib

    sa, sb = normalized_slides(a), normalized_slides(b)
    if len(sa) != len(sb):
        return f"slide count differs: {len(sa)} rendered, {len(sb)} built"
    for i, (x, y) in enumerate(zip(sa, sb)):
        if x != y:
            diff = difflib.unified_diff(x.splitlines(), y.splitlines(), f"render/slide{i + 1}", f"build/slide{i + 1}", lineterm="", n=2)
            return "\n".join(list(diff)[:60])
    return None
